use Symfony\Component\DependencyInjection\Attribute\AsTaggedItem;
use TYPO3\CMS\Core\Scope\ScopeInterface;
use TYPO3\CMS\Core\Scope\ScopeUser;

#[AsTaggedItem(index: 'my-extension:news:read')]
final class NewsReadScope implements ScopeInterface
{
    public function getName(): string { return 'Read access to news'; }
    public function getDescription(): string { return 'Read news records.'; }
    public function getIcon(): string { return 'content-news'; }

    // Decides whether a user may hold this scope at all
    public function allowedForUser(ScopeUser $user): bool { return true; }
}

use TYPO3\CMS\Core\Action\ActionType;
use TYPO3\CMS\Core\Action\Link;
use TYPO3\CMS\Core\Action\Target;
use TYPO3\CMS\Core\Attribute\AsAction;

// Version 1 stays available and sends the header Deprecation
#[AsAction(route: 'my-extension/news/latest', description: 'Superseded by version 2', deprecated: 1793608038)]
public function latest(int $limit = 10): array { … }

// GET /typo3/api/v2/my-extension/news/latest, MCP tool fetch_my_extension_news_latest_v2
#[AsAction(route: 'my-extension/news/latest', version: 2)]
public function latestV2(int $limit = 10, int $offset = 0): array { … }

// POST /typo3/api/v1/my-extension/news returns 201 and Location: …/typo3/api/v1/my-extension/news/42
#[AsAction(
    route: 'my-extension/news',
    type: ActionType::create,
    location: new Link([NewsActions::class, 'show'], ['uid' => '$response.body#/uid']),
)]
public function create(string $title, string $teaser): array { … }

// Only for the backend: no HTTP API for apps, no MCP tool
#[AsAction(route: 'my-extension/news/preview', type: ActionType::dispatch, targets: [Target::backend])]
public function preview(int $uid): array { … }
